    /// The identity map on `Bivector`: a `Bivector` with one open `Bivector` slot.
    #[inline(always)]
    pub fn slot() -> Bivector<(Bivector,), T> {
        Bivector { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e23`.
    #[inline(always)]
    pub fn e23(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e31`.
    #[inline(always)]
    pub fn e31(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e12`.
    #[inline(always)]
    pub fn e12(&self) -> T {
        self.c[2]
    }
