impl<T: gx::Real> Bivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[0].mul_add(x[0], t1);
        let t4 = x[2].mul_add(x[2], t3);
        t4
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (16 mul, 7 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Bivector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t5 = t0 * t2;
        let t6 = t1 * t1;
        let t9 = t0.mul_add(t0, t6);
        let t10 = t2.mul_add(t2, t9);
        let t11 = t0.mul_add(t1, t5);
        let t12 = t1.mul_add(t2, t11);
        let t14 = t12.mul_add(T::from_i64(2), t10);
        let t15 = t14.recip();
        let t17 = t1 * t15;
        let t19 = t0.mul_add(t15, t17);
        let t20 = t2.mul_add(t15, t19);
        let t21 = x[0] * t20;
        let t22 = x[1] * t20;
        let t23 = x[2] * t20;
        let t24 = -t21;
        let t25 = -t22;
        let t26 = -t23;
        Bivector::from_coeffs([t24, t25, t26])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[0].mul_add(x[0], p1);
        let p4 = x[2].mul_add(x[2], p3);
        let s0 = (p4).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Bivector::from_coeffs([t0, t1, t2]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Rotor<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[0].mul_add(x[0], p1);
        let p4 = x[2].mul_add(x[2], p3);
        let p5 = -p4;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs_rotation(p5, T::from_i64(0));
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([c0, t0, t1, t2]))
        })
    }

}

impl<T: gx::Coef> gx::NewtonStep for Bivector<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[0].mul_add(x[0], t1);
        let t4 = x[2].mul_add(x[2], t3);
        let t6 = (-t4).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t7 = x[0] * t6;
        let t8 = x[1] * t6;
        let t9 = x[2] * t6;
        let t10 = t7 * T::from_ratio(3, 2);
        let t11 = t8 * T::from_ratio(3, 2);
        let t12 = t9 * T::from_ratio(3, 2);
        Bivector::from_coeffs([t10, t11, t12])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

